## Submitted testbench
```systemverilog
`timescale 1ns / 1ps

module tb;

  // Parameters
  localparam int CLK_PERIOD = 8;

  // Clock and reset
  logic clk = 0;
  always #(CLK_PERIOD/2) clk = ~clk;

  logic rst = 0;

  // AXI stream interface signals
  logic [7:0] s_axis_tdata;
  logic       s_axis_tvalid;
  wire        s_axis_tready;

  // DUT internal signals (outputs)
  logic [7:0] m_axis_tdata;
  logic       m_axis_tvalid;
  logic       txd;
  logic       tx_busy;
  logic       rx_busy;
  logic       rx_overrun_error;
  logic       rx_frame_error;
  logic       rxd;

  // Configuration
  logic [15:0] prescale_val = 16'd1;

  // Tie off unused input
  initial rxd = 1'b1;

  // Instantiate DUT with all ports connected
  uart #(.DATA_WIDTH(8)) dut (
    .clk          (clk),
    .rst          (rst),
    .s_axis_tdata (s_axis_tdata),
    .s_axis_tvalid(s_axis_tvalid),
    .s_axis_tready(s_axis_tready),
    .m_axis_tdata (m_axis_tdata),
    .m_axis_tvalid(m_axis_tvalid),
    .rxd          (rxd),
    .txd          (txd),
    .tx_busy      (tx_busy),
    .rx_busy      (rx_busy),
    .rx_overrun_error(rx_overrun_error),
    .rx_frame_error (rx_frame_error),
    .prescale     (prescale_val)
  );

  // Task to drive AXI‑Stream with a single byte
  task automatic send_byte(input byte unsigned b);
    begin
      // Drive data and assert valid
      s_axis_tdata  = b;
      s_axis_tvalid = 1'b1;

      // Wait until the DUT asserts tready (handshake)
      while (!s_axis_tready) @(negedge clk);

      // One more clock to let the handshake complete, then deassert valid
      @(negedge clk);
      s_axis_tvalid = 1'b0;
    end
  endtask

  // Test sequence
  initial begin
    // Reset timing
    rst = 0;
    #10ns;
    rst = 1;
    #10ns;
    rst = 0;
    #10ns;

    // Configure prescale to 1
    prescale_val = 16'd1;

    // Send two back‑to‑back frames (any data payloads are acceptable)
    send_byte(8'hA5);
    send_byte(8'h5A);

    // Allow sufficient time for the coverage property to be observed
    #500000ns;

    $finish;
  end

endmodule
```

